import React from 'react'
import Navbar from '../Home/Navbar';
import { CartProvider, useCart } from 'react-use-cart'
import { Link } from 'react-router';

function Cart (){
    const {items,totalUniqueItems,totalItems,cartTotal,updateItemQuantity,removeItem,emptyCart,isEmpty} = useCart();
    if(isEmpty){
        return(
            <div className='text-center'>
                <img src="/img/cart.png"></img>
                <h5 className='text-center'>Your Cart is Empty...</h5>
            </div>
        )
    }
    return(
        <div>
            <div className='container pt-5'>
                <div className='row'>
                    <div className='col-md-10 m-auto'>
                        <h3 className='text-center'>Cart({totalUniqueItems})
                            <button onClick={()=>emptyCart()} className='btn btn-danger'>Empty Cart</button>
                        </h3>
                        <table className='table table-dark text-center'>
                               <thead>
                                <tr>
                                    <th>Image</th>
                                    <th>Name</th>
                                    <th>Quantity</th>
                                    <th>Price</th>
                                    <th>Opreation</th>
                                </tr>
                               </thead>
                               <tbody>
                                {items.map((element)=>{
                                    return(
                                        <tr>
                                            <td><img src={element.images[0]} style={{width:"90px"}}></img></td>
                                            <td>{element.title}</td>
                                            <td>{element.quantity}</td>
                                            <td>{Math.ceil(element.price*element.quantity)}$</td>
                                            <td>
                                                <button className='btn btn-warning' onClick={()=>updateItemQuantity(element.id,element.quantity-1)}>-</button>
                                                <button className='btn btn-success mx-3' onClick={()=>updateItemQuantity(element.id,element.quantity+1)}>+</button>
                                                <button className='btn btn-danger' onClick={()=>removeItem(element.id)}>&items;</button>
                                            </td>
                                        </tr>
                                    )
                                } )}
                               </tbody>
                               <tfoot>
                                <tr>
                                    <td>Total</td>
                                    <td>------</td>
                                    <td>{totalItems}</td>
                                    <td>{Math.ceil(cartTotal)}$</td>
                                    <td>
                                        <Link to="/products" className='btn btn-primary mr-2'>ContinueShoping</Link>
                                        <Link to="/products" className='btn btn-success'>Payment</Link>
                                    </td>
                                </tr>
                               </tfoot>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    )
}

function AllCart() {
  return (
    <CartProvider>
       <Navbar/>
       <br></br>
       <br></br>
       <br></br>
       <br></br>
       <Cart/>
    </CartProvider>
  )
}

export default AllCart