import React, { useEffect, useState } from 'react';
import Navbar from '../Home/Navbar';
import { Link, useParams } from 'react-router';
import axios from "axios";

function AllSingleProduct() {
    const { id } = useParams();
    const [text,setText] = useState({});
    useEffect(() => {
        axios.get(`https://dummyjson.com/products/${id}`)
        .then( (element)=>{
            setText(element.data);
        });
    },[]);
  return (
    <div>
        <Navbar/>
        <br></br>
        <br></br>
        <br></br>
        <br></br>
        <div className="container">

                <div className='row'>
                    <div className='col-md-6'>
                        <img src={text.images} className="w-75"></img>
                    </div>
                    <div className="col-md-6 text-center mt-5 pt-5"></div>
                    <h4>Name:{text.title}</h4>
                    <h5 className="mt-4">Brand:{text.brand}</h5>
                    <h5 className="mt-4">Category:{text.category}</h5>
                    <h5 className="mt-4">Stock:{text.stock}</h5>
                    <h5 className="mt-4">Rating:{text.rating}</h5>
                    <h5 className="mt-4">Discount:{text.discountPercentage}%</h5>
                    <h5 className="mt-4">Price:{text.price}$</h5>
                    <h5 className="mt-4">Id:{text.id}</h5>
                    <Link to="/products" className="btn btn-dark btn-block">Back</Link>
                </div>
            ;        
    </div>
    </div>
  )
}

export default AllSingleProduct