import React, { useContext, useEffect, useState } from "react"
import Navbar from "../Home/Navbar";
import axios from "axios";
import { Link } from "react-router";
import { apiValue } from "../Data/AllData";
import { CartProvider, useCart } from "react-use-cart";


function Page () {
 const [search, setSearch] = useState(0); 
 const getValue = (event)=>{
   setSearch(event.target.value);
  };
  const data = useContext(apiValue)

const {addItem} = useCart();


  return(
    <div>
         <div className="container">
          <div className="row">
            <div className="col-md-10 m-auto">
              <input
               onChange={getValue}
              className="form-control"
              placeholder="Search"
              />
            </div>
            {data.map((item) => {
              return search == 0 ? (
                <div className="col-md-4 text-centre mb-5">
                  <img src={item.images[0]} className="w-100"></img>

            <Link to={`/singleproduct/${item.id}`} className="btn btn-dark btn-block"
            >
             Details
          </Link>
          <button onClick={()=>addItem(item)} className="btn btn-dark btn-block">Add To Cart</button>
         </div>
         ) : item.id == search ? (
           <div className="col-md-4 text-centre mb-5">
          <img src={item.images[0]} className="w-100"></img>
          <h4>{item.title}</h4>
          <h5>{item.brand}</h5>
          <h5>{item.price}$</h5>
          <h5>{item.id}</h5>
           <button onClick={()=>addItem(item)} className="btn btn-dark btn-block">Add To Cart</button>
         </div>
  ) : item.title.toUpperCase().includes(search.toUpperCase()) ? (
    <div className="col-md-4 text-center mb-5">
      <img src={item.images[0]} className="w-100"></img>
      <h4>{item.title}</h4>
      <h5>{item.brand}</h5>
      <h5>{item.price}$</h5>
      <h5>{item.id}</h5>
      <button onClick={()=>addItem(item)} className="btn btn-dark btn-block">Add To Cart</button>
    </div>
  ) : null;
})}
      </div>
    </div>
  </div>
  )
}



function AllProducts() {

  return (
    <CartProvider>
        <Navbar/>
        <br></br>
        <br></br>
        <br></br>
        <br></br>
        <br></br>
        <Page/>
    </CartProvider>
  );
}

export default AllProducts