import React from 'react'

// condition ? true:condition?true:false 

function Cart({allData}) {
  return (
    <div>
        {allData.map( (item)=>{

                return item.id>=3? (
                    <div>
                        <h2>My Name is {item.firstName} {item.lastName} </h2>
                        <h2>My Color is {item.color}</h2>
                        <h5>My Color is {item.id} </h5>
                        <hr></hr>
                    </div>
                ): item.id==1?(
                    <div>
                        <h2>Not In Range</h2>
                    </div>
                ):(
                    <div>
                        <h1>Hiii</h1>
                    </div>
                )
          
                return(
                   <div>
                    <h1>Hiiii</h1>
                    </div>
                )
            
        })}
    </div>
  )
}

export default Cart